public enum ModelServeError: Swift.Error {



    case RequestFailed(message: String)

    case Cancelled(message: String)

    case Unknown(message: String)

}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeModelServeError: FfiConverterRustBuffer {
    typealias SwiftType = ModelServeError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ModelServeError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .RequestFailed(
            message: try FfiConverterString.read(from: &buf)
        )

        case 2: return .Cancelled(
            message: try FfiConverterString.read(from: &buf)
        )

        case 3: return .Unknown(
            message: try FfiConverterString.read(from: &buf)
